-- 插入 product_library 表数据
DELETE FROM "product_library";
SELECT setval(pg_get_serial_sequence('product_library', 'id'), (SELECT COALESCE(MAX(id), 0) FROM "product_library"));



-- 插入 sub_devices 表数据
DELETE FROM "sub_devices";
SELECT setval(pg_get_serial_sequence('"sub_devices"', 'id'), (SELECT MAX(id) FROM "sub_devices"));



-- 插入 sensor_type_model_mapping 表数据
DELETE FROM "sensor_type_model_mapping";
SELECT setval(pg_get_serial_sequence('sensor_type_model_mapping', 'id'), (SELECT COALESCE(MAX(id), 0) FROM "sensor_type_model_mapping"));



-- 插入formula 表数据
DELETE FROM "formula";
SELECT setval(s.seq, (SELECT COALESCE(MAX(id), 0) FROM "formula"))
FROM (SELECT pg_get_serial_sequence('formula','id') AS seq) s
WHERE s.seq IS NOT NULL;



